public static class MaintenanceTests {
    [DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr context);
    static readonly List<string> passed=new List<string>();static string root;static int code;
    static T Field<T>(object obj,string name){return (T)obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);}
    static void Set(object obj,string name,object value){obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(obj,value);}
    static object Call(object obj,string name,params object[] args){return obj.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,args);}
    static void Check(bool value,string name){if(!value)throw new Exception(name);passed.Add(name);Console.WriteLine("PASS: "+name);}
    static bool Near(double a,double b){return Math.Abs(a-b)<.00001;}
    static async Task Until(Func<bool> check,string name,int timeout=20000){var watch=Stopwatch.StartNew();while(!check()){if(watch.ElapsedMilliseconds>timeout)throw new Exception("Timed out: "+name);await Task.Delay(25);}}
    static IEnumerable<Control> All(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(Control x in All(c))yield return x;}}
    static void Inspect(Control parent){foreach(Control c in parent.Controls){if(c.Visible&&(c.Width<=0||c.Height<=0||c.Left<0||c.Top<0||c.Right>parent.ClientSize.Width+1||c.Bottom>parent.ClientSize.Height+1))throw new Exception("Clipped "+c.GetType().Name+" "+c.Text+" in "+parent.GetType().Name);if(!(c is NumericUpDown)&&!(c is TextBoxBase)&&!(c is ComboBox))Inspect(c);}}
    static void Snapshot(Form form,string name){Inspect(form);using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(Point.Empty,form.Size));bmp.Save(Path.Combine(root,name+".png"));}}
    static string Entry(CacheStore store,int size=10){using(var lease=store.Create()){using(var file=new FileStream(Path.Combine(lease.Directory,"formula.dvi"),FileMode.Create))file.SetLength(size);return lease.Directory;}}
    static async Task Core(){
        string prefs=Path.Combine(root,"preferences.json");File.WriteAllText(prefs,"{\"Version\":1,\"Font\":\"times\",\"Size\":14,\"Zoom\":200}");var storage=new SettingsStore(prefs);var p=storage.Load();
        Check(p.Font=="times"&&p.Size==14&&!p.AutoUpdate&&p.AutoClean&&p.CacheLimitMB==20&&p.CacheDays==7,"Old settings upgrade with auto-update off and 20 MB / 7 day defaults");
        p.AutoUpdate=true;p.AutoClean=false;p.CacheLimitMB=30;p.CacheDays=3;p.TexDirectory=Path.Combine(root,"custom tex");storage.Save(p);p=storage.Load();Check(p.AutoUpdate&&!p.AutoClean&&p.CacheLimitMB==30&&p.CacheDays==3&&p.TexDirectory.EndsWith("custom tex"),"New preferences survive save/reload");
        p.CacheLimitMB=-1;p.CacheDays=900;p.Validate();Check(p.CacheLimitMB==20&&p.CacheDays==7,"Invalid cache limits revert to defaults");
        string rootCache=Path.Combine(root,"owned-cache"),legacy=Path.Combine(root,"legacy");var store=new CacheStore(rootCache,legacy);
        using(var lease=store.Create()){
            File.WriteAllText(Path.Combine(lease.Directory,"formula.svg"),"<svg/>");var pin=lease.Retain();lease.Dispose();var report=store.Clean(true,20,7);Check(report.RemovedEntries==0&&report.ProtectedEntries==1&&File.Exists(Path.Combine(lease.Directory,"formula.svg")),"Retained cache survives cleanup after renderer ownership ends");pin.Dispose();
        }
        Check(store.Clean(true,20,7).RemovedEntries==1,"Released cache becomes removable");
        string readOnly=Entry(store);string readOnlyFile=Path.Combine(readOnly,"formula.dvi");File.SetAttributes(readOnlyFile,FileAttributes.ReadOnly);var readonlyReport=store.Clean(true,20,7);Check(readonlyReport.ProtectedEntries==1&&readonlyReport.RemovedBytes==0&&File.Exists(Path.Combine(readOnly,".vf-cache")),"Read-only entries are preserved with their cache marker");File.SetAttributes(readOnlyFile,FileAttributes.Normal);Check(store.Clean(true,20,7).RemovedEntries==1,"Writable cache becomes cleanable after read-only protection is removed");
        string old=Entry(store),fresh=Entry(store);File.SetLastWriteTimeUtc(Path.Combine(old,".vf-cache"),DateTime.UtcNow.AddDays(-8));store.Clean(false,20,7);Check(!Directory.Exists(old)&&Directory.Exists(fresh),"Age cleanup removes expired entries and keeps fresh ones");store.Clean(true,20,7);
        for(int i=0;i<22;i++){string dir=Entry(store,1024*1024);File.SetLastWriteTimeUtc(Path.Combine(dir,".vf-cache"),DateTime.UtcNow.AddMinutes(-22+i));}
        var budget=store.Clean(false,20,7);Check(budget.RemovedEntries>=3&&store.Inspect().Bytes<=20L*1024*1024,"20 MB budget removes oldest eligible entries");store.Clean(true,20,7);
        string odd=Entry(store);File.WriteAllText(Path.Combine(odd,"personal.txt"),"keep");string ordinary=Path.Combine(rootCache,"notes");Directory.CreateDirectory(ordinary);File.WriteAllText(Path.Combine(ordinary,"formula.svg"),"keep");
        store.Clean(true,20,7);Check(File.Exists(Path.Combine(odd,"personal.txt"))&&Directory.Exists(ordinary),"Unrecognized files and non-cache directories are never deleted");
        Directory.CreateDirectory(legacy);string oldDir=Path.Combine(legacy,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(oldDir);File.WriteAllText(Path.Combine(oldDir,"formula.tex"),"sample");store.Clean(true,20,7);Check(Directory.Exists(oldDir),"Legacy cache is excluded unless explicitly selected");store.Clean(true,20,7,true);Check(!Directory.Exists(oldDir),"Recognized legacy cache can be cleaned explicitly");
        string junction=Environment.GetEnvironmentVariable("VF_TEST_JUNCTION");if(string.IsNullOrEmpty(junction))throw new Exception("Junction fixture missing");var external=new CacheStore(Environment.GetEnvironmentVariable("VF_TEST_EXTERNAL"));string safe=Entry(external);var linked=new CacheStore(junction);Check(linked.Clean(true,20,7).RemovedEntries==0&&Directory.Exists(safe),"Cleanup refuses a junction root and preserves its target");
        string childReady=Path.Combine(root,"child-ready.txt"),release=Path.Combine(root,"child-release.txt");
        using(var child=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--hold \""+rootCache+"\" \""+childReady+"\" \""+release+"\""){UseShellExecute=false,CreateNoWindow=true}))try{
            await Until(()=>File.Exists(childReady),"child lease");string held=File.ReadAllText(childReady);Check(store.Clean(true,20,7).ProtectedEntries>=1&&Directory.Exists(held),"Another process's active cache survives manual cleanup");File.WriteAllText(release,"release");await Until(()=>child.HasExited,"child release");store.Clean(true,20,7);Check(!Directory.Exists(held),"Other process's cache is removable after its lease closes");
        }finally{if(!child.HasExited)child.Kill();}
        string tools=Path.Combine(root,"fake tools");Directory.CreateDirectory(tools);File.WriteAllText(Path.Combine(tools,"latex.exe"),"");Check(Toolchain.Resolve("latex",null,new[]{tools})==Path.Combine(tools,"latex.exe"),"Tool resolution supports paths with spaces");
        bool rejected=false;try{Toolchain.Resolve("latex",Path.Combine(root,"missing"),new[]{tools});}catch(IOException){rejected=true;}Check(rejected,"Invalid explicit TeX path does not silently use another installation");
        string tex=Path.GetDirectoryName(Renderer.FindTool("latex"));string configApp=Path.Combine(root,"config-app");Directory.CreateDirectory(configApp);File.WriteAllText(Path.Combine(configApp,"tex-bin.txt"),tex);Check(Toolchain.CandidateDirectories(configApp).First()==tex,"Existing tex-bin.txt retains discovery priority");
        string badSettings=Path.Combine(root,"not-a-directory");File.WriteAllText(badSettings,"keep");var rows=await Task.Run(()=>EnvironmentInspector.Basic(Path.Combine(root,"missing"),Path.Combine(badSettings,"settings.json"),store,Path.Combine(root,"missing-assets"),CancellationToken.None));
        Check(rows.Count(r=>r.Name=="latex"&&r.Problem)==1&&rows.Any(r=>r.Name=="dvisvgm"&&r.Problem),"Missing TeX tools yield actionable diagnostic rows");Check(rows.Any(r=>r.Name=="设置与草稿"&&r.Problem)&&rows.Any(r=>r.Name=="离线 MathJax"&&r.Problem),"Unwritable settings and missing offline resources are reported");Check(rows.Count(r=>r.State=="待测试")==7,"Quick checks distinguish untested fonts from verified availability");
        int exit;bool timeout=false;try{Toolchain.Execute(Application.ExecutablePath,"--sleep",root,100,CancellationToken.None,out exit);}catch(TimeoutException){timeout=true;}Check(timeout,"Diagnostic subprocess timeout terminates hung tool");
        bool canceled=false;using(var cts=new CancellationTokenSource()){cts.CancelAfter(100);try{await Task.Run(()=>{int result;Toolchain.Execute(Application.ExecutablePath,"--sleep",root,5000,cts.Token,out result);});}catch(OperationCanceledException){canceled=true;}}Check(canceled,"Diagnostic cancellation terminates child tool");
        string output=Toolchain.Execute(Application.ExecutablePath,"--flood",root,5000,CancellationToken.None,out exit);Check(exit==0&&output.Length>=180000,"Concurrent stdout/stderr draining avoids pipe deadlock");
        using(var rendered=Renderer.Render(new Formula{Source="a+b"})){string file=rendered.Svg;CacheStore.Default.Clean(true,20,7);Check(File.Exists(file),"Active exact result survives full cleanup");}CacheStore.Default.Clean(true,20,7);
    }
    static async Task Dialogs(MainForm form,bool full){
        if(full){
            var preferences=Field<Preferences>(form,"preferences");preferences.AutoClean=false;preferences.EnvironmentChecked=false;Call(form,"StartupCheck");await Until(()=>preferences.EnvironmentChecked,"first startup check");Check(Field<SettingsStore>(form,"settings").Load().EnvironmentChecked,"First-start diagnostics complete without a modal and persist their state");
            string aged=Entry(CacheStore.Default);File.SetLastWriteTimeUtc(Path.Combine(aged,".vf-cache"),DateTime.UtcNow.AddDays(-8));await Task.Delay(2000);await (Task)Call(form,"CleanIdle");Check(Directory.Exists(aged),"Disabled automatic cleanup preserves expired cache");preferences.AutoClean=true;await (Task)Call(form,"CleanIdle");Check(!Directory.Exists(aged)&&File.Exists(Field<Rendered>(form,"ready").Svg),"Idle automatic cleanup removes expired files and protects the visible result");
        }
        Check(!All(form).OfType<CheckBox>().Any(),"Main window has no auto-update checkbox");
        using(var dialog=new AppSettingsDialog(false,null,null,null){Opacity=0}){dialog.Show();Snapshot(dialog,"settings");Check(!dialog.AutoUpdate,"Auto-update defaults to off inside settings");Field<CheckBox>(dialog,"autoUpdate").Checked=true;All(dialog).OfType<Button>().Single(b=>b.Text=="保存").PerformClick();Check(dialog.DialogResult==DialogResult.OK&&dialog.AutoUpdate,"Settings save returns the enabled preference");}
        using(var dialog=new AppSettingsDialog(false,null,null,null){Opacity=0}){dialog.Show();dialog.Size=dialog.MinimumSize;Snapshot(dialog,"settings-minimum");Field<CheckBox>(dialog,"autoUpdate").Checked=true;All(dialog).OfType<Button>().Single(b=>b.Text=="取消").PerformClick();Check(dialog.DialogResult==DialogResult.Cancel,"Settings cancellation leaves caller preference unchanged");}
        using(var dialog=new CacheDialog(new CacheStore(Path.Combine(root,"dialog-cache")),new Preferences()){Opacity=0}){dialog.Show();await Until(()=>!Field<bool>(dialog,"working")&&Field<Label>(dialog,"summary").Text.StartsWith("共 "),"cache stats");Snapshot(dialog,"cache");dialog.Size=dialog.MinimumSize;Snapshot(dialog,"cache-minimum");Check(dialog.LimitMB==20&&dialog.Days==7&&dialog.AutoClean,"Cache dialog exposes 20 MB / 7 day defaults");Field<Button>(dialog,"clean").PerformClick();await Until(()=>!Field<bool>(dialog,"working"),"manual cleanup");Check(Field<Label>(dialog,"message").Text.Contains("已释放"),"Manual cleanup reports actual released space");dialog.Close();}
        await Until(()=>Field<Rendered>(form,"ready")!=null,"main preview");
        Func<CancellationToken,Task<Rendered>> render=token=>(Task<Rendered>)Call(form,"RenderExactAsync",new Formula{Font="mathjax",Source=@"\text{test}\quad\bm{\alpha}=\frac{1}{s+1}\quad\color{blue}\begin{bmatrix}1&0\\0&1\end{bmatrix}"},token);
        using(var dialog=new EnvironmentDialog("",Path.Combine(root,"env-settings.json"),render){Opacity=0}){
            dialog.Show();await Until(()=>!Field<bool>(dialog,"working")&&Field<List<CheckResult>>(dialog,"results").Count>=13,"environment basic");Snapshot(dialog,"environment");dialog.Size=dialog.MinimumSize;Snapshot(dialog,"environment-minimum");Check(Field<List<CheckResult>>(dialog,"results").Count>=13,"Environment dialog reports tools, resources, storage and seven fonts");
            if(full){await (Task)Call(dialog,"Check",true);var fonts=Field<List<CheckResult>>(dialog,"results");Check(fonts.Count(r=>r.State=="渲染通过")==7,"All seven fonts actually render through environment test");Snapshot(dialog,"environment-tested");}
            dialog.Close();
        }
        if(full)using(var dialog=new EnvironmentDialog(Path.Combine(root,"no-tex"),Path.Combine(root,"env-settings.json"),async token=>{await Task.Delay(5000,token);return (Rendered)null;}){Opacity=0}){
            dialog.Show();await Until(()=>!Field<bool>(dialog,"working")&&Field<List<CheckResult>>(dialog,"results").Count>=13,"cancel fixture ready");var running=(Task)Call(dialog,"Check",true);await Until(()=>Field<Label>(dialog,"message").Text.Contains("MathJax · TeX"),"cancel during font test");dialog.Close();await running;Check(!dialog.IsDisposed&&Field<Label>(dialog,"message").Text.Contains("已取消"),"Closing during a diagnostic safely cancels and preserves completed rows");dialog.Close();
        }
        if(full)using(var dialog=new EnvironmentDialog(Path.Combine(root,"no-tex"),Path.Combine(root,"env-settings.json"),render){Opacity=0}){dialog.Show();await Until(()=>!Field<bool>(dialog,"working")&&Field<List<CheckResult>>(dialog,"results").Count>=13,"missing tools");await (Task)Call(dialog,"Check",true);var rows=Field<List<CheckResult>>(dialog,"results");Check(rows.Single(r=>r.Name=="MathJax · TeX").State=="渲染通过"&&rows.Count(r=>r.State=="渲染失败")==6,"MathJax remains usable when local TeX is missing");dialog.Close();}
    }
    static void EnableInSettings(MainForm form,bool enabled=true){using(var timer=new System.Windows.Forms.Timer{Interval=50}){timer.Tick+=delegate{var dialog=Application.OpenForms.OfType<AppSettingsDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();Field<CheckBox>(dialog,"autoUpdate").Checked=enabled;All(dialog).OfType<Button>().Single(b=>b.Text=="保存").PerformClick();};timer.Start();Call(form,"ConfigureApplication");}}
