            Check((int)shape.ID==id&&Near(Bridge.Get(shape,"PinX"),x)&&Near(Bridge.Get(shape,"PinY"),y)&&Near(Bridge.Get(shape,"Angle"),.2)&&Near(Bridge.Get(shape,"Width")/Bridge.Read(shape).BaseWidth,1.4),"Auto-update preserves identity, center, rotation and 1.4x scale");
            Call(form,"Schedule",true);await Until(()=>Field<Rendered>(form,"ready")!=null,"same content rerender");await Task.Delay(800);a.Undo();Check(Bridge.Read(shape).Source=="x+1","Unchanged exact results create no extra Visio undo entry");await Until(()=>Field<UpdateBinding>(form,"binding").Paused,"undo pause");await Task.Delay(800);Check(Bridge.Read(shape).Source=="x+1","Visio undo is not overwritten by automatic resync");
            source.Text="x+3";await Until(()=>Field<Rendered>(form,"ready")!=null,"paused preview");await Task.Delay(750);Check(Bridge.Read(shape).Source=="x+1","External-change pause persists across new source input");Call(form,"UpdateSelected");Check(Bridge.Read(shape).Source=="x+3"&&!Field<UpdateBinding>(form,"binding").Paused,"Explicit manual update refreshes binding and resumes sync");
            a.ActiveWindow.DeselectAll();a.ActiveWindow.Select(neighbor,2);source.Text="x+4";await Until(()=>Bridge.Read(shape).Source=="x+4","fixed target");Check(Bridge.Read(neighbor).Source=="x+1","Changing Visio selection cannot redirect auto-update");
