            for(int i=0;i<12;i++){source.Text="x+"+(100+i);await Task.Delay(30);}await Until(()=>Bridge.Read(shape).Source=="x+111","latest source");a.Undo();Check(Bridge.Read(shape).Source=="x+4","Rapid edits coalesce into one latest-result update");await Until(()=>Field<UpdateBinding>(form,"binding").Paused,"second undo pause");
            a.ActiveWindow.DeselectAll();a.ActiveWindow.Select(shape,2);Call(form,"ReadSelected");await Until(()=>Field<Rendered>(form,"ready")!=null,"rebind");Field<ComboBox>(form,"font").SelectedIndex=FontCatalog.IndexOf("mathjax");Field<NumericUpDown>(form,"size").Value=14;source.Text=@"\frac{a+b}{c}";await Until(()=>Bridge.Read(shape).Font=="mathjax"&&Bridge.Read(shape).Size==14,"font/size sync");Check(Near(Bridge.Get(shape,"Width"),Field<Rendered>(form,"ready").Width),"Explicit font/point-size changes sync at natural size");
            b=Activator.CreateInstance(Type.GetTypeFromProgID("Visio.Application"));b.AlertResponse=7;b.Visible=false;other=b.Documents.Add("");second=new Bridge((object)b);dynamic otherShape;using(var r=Renderer.Render(new Formula{Source="b+1"}))otherShape=other.Pages[1].Drop(second.GetDragData(r),3,3);Set(form,"bridge",second);
            source.Text="x+222";await Until(()=>Bridge.Read(shape).Source=="x+222","owner switch");Check(Bridge.Read(otherShape).Source=="b+1","Auto-update stays with original owner after bridge connects elsewhere");a.Undo();Check(Bridge.Read(shape).Source==@"\frac{a+b}{c}","Auto-update undo belongs to target's Visio instance");await Until(()=>Field<UpdateBinding>(form,"binding").Paused,"owner undo pause");Set(form,"bridge",bridge);a.ActiveWindow.DeselectAll();a.ActiveWindow.Select(shape,2);Call(form,"ReadSelected");
            Field<ComboBox>(form,"font").SelectedIndex=0;source.Text=@"\frac{1}{s+123}";await Task.Delay(280);await Task.Run(()=>CacheStore.Default.Clean(true,20,7));await Until(()=>Bridge.Read(shape).Source==@"\frac{1}{s+123}","cleanup during render");Check(File.Exists(Field<Rendered>(form,"ready").Svg),"Cleanup during exact compilation preserves final automatic update");
