            source.Text="x+oldtarget";a.ActiveWindow.DeselectAll();a.ActiveWindow.Select(neighbor,2);Call(form,"ReadSelected");source.Text="n+2";await Until(()=>Bridge.Read(neighbor).Source=="n+2","new explicit target");Check(Bridge.Read(shape).Source=="x+disabled","Explicitly loading a new target invalidates the previous pending update");
