        }finally{Set(form,"bridge",null);Call(form,"ClearTarget");if(bridge!=null)bridge.Dispose();if(second!=null)second.Dispose();if(doc!=null)try{doc.Saved=true;doc.Close();}catch{}if(other!=null)try{other.Saved=true;other.Close();}catch{}if(a!=null)try{a.Quit();}catch{}if(b!=null)try{b.Quit();}catch{}}
