    [STAThread]public static int Main(string[] args){
        if(args.Contains("--sleep")){Thread.Sleep(5000);return 0;}if(args.Contains("--flood")){Console.Write(new string('a',100000));Console.Error.Write(new string('b',100000));return 0;}
        if(args.Length>0&&args[0]=="--hold"){using(var lease=new CacheStore(args[1]).Create()){File.WriteAllText(Path.Combine(lease.Directory,"formula.svg"),"<svg/>");File.WriteAllText(args[2],lease.Directory);var watch=Stopwatch.StartNew();while(!File.Exists(args[3])&&watch.ElapsedMilliseconds<30000)Thread.Sleep(25);}return 0;}
        bool dpi96=args.Contains("--96"),visio=args.Contains("--visio");if(dpi96)SetThreadDpiAwarenessContext(new IntPtr(-1));
        root=Path.Combine(Environment.GetEnvironmentVariable("VF_MAINTENANCE_TEST_ROOT"),visio?"visio":dpi96?"96":"native");Directory.CreateDirectory(root);
        Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var form=new MainForm(new SettingsStore(Path.Combine(root,"isolated-settings.json"))){Opacity=0,ShowInTaskbar=false};
        form.Shown+=async delegate{try{if(visio)await Visio(form);else{if(!dpi96)await Core();await Dialogs(form,!dpi96);}}catch(Exception e){code=1;Console.WriteLine(e);File.WriteAllText(Path.Combine(root,"failure.txt"),e.ToString());}finally{File.WriteAllText(Path.Combine(root,"results.json"),new JavaScriptSerializer().Serialize(new{passed=passed}));form.Close();}};
        Application.Run(form);return code;
    }
